/* 19 slider */
async function slider(){
  const T=tile('mk-sl'),S=ms=>sleep(ms,T),fill=$('.fill',T),kn=$('.kn',T),vn=$('.vnum',T),tk=$('.ticks',T);
  tk.innerHTML='<i></i>'.repeat(21);const ticks=$$('i',tk);
  let v=72;
  const draw=()=>{fill.style.width=v+'%';kn.style.left=v+'%';vn.textContent=Math.round(v)+'%';
    ticks.forEach((x,k)=>{const d=Math.abs(k*5-v);x.style.height=(d<12?4+(12-d)*.6:4)+'px';x.style.background=k*5<=v?'#3e6dec':'#d4d4d4';});};
  const tween=(to,dur)=>new Promise(r=>{const f=v,t0=performance.now();const st=n=>{if(paused||!T._vis){requestAnimationFrame(st);return;}const k=Math.min(1,(n-t0)/dur),e=k<.5?4*k*k*k:1-Math.pow(-2*k+2,3)/2;v=f+(to-f)*e;draw();k<1?requestAnimationFrame(st):r();};requestAnimationFrame(st);});
  draw();await hold();
  for(;;){for(const to of [30,62,100,72]){await S(700);kn.classList.add('drag');await tween(to,900);await S(250);kn.classList.remove('drag');}}
}
/* 20 focus timer */
function timer(){
  const T=tile('mk-ft'),tm=$('.ftime',T),bar=$('.fbar',T);
  const TOTAL=300;let left=297;
  const fmt=s=>String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');
  const draw=()=>{rollStr(tm,fmt(left),1);bar.style.transform=`scaleX(${1-left/TOTAL})`;};
  rollStr(tm,fmt(left),0);bar.style.transform=`scaleX(${1-left/TOTAL})`;
  if(RM)return;
  setInterval(()=>{if(paused||!T._vis)return;left=left>0?left-1:TOTAL;draw();},1000);
}


